// api.js
const express = require('express');
const router = express.Router();

router.get('/cascades', (req, res) => {
    // Check if fetching all cascades returns correct data
    try {
        const cascades = fetchCascades(); // Fetching logic
        res.json(cascades);
    } catch (error) {
        return res.status(500).json({ error: error.message });
    }
});

module.exports = router;
```

It seems like the function `fetchCascades` is not implemented or imported in your `api.js`. Let's define it in the `utils` directory or ensure it's correctly imported.

```javascript
