    // Simulating data fetching
    return [{ id: 1, name: 'Test Cascade' }];
};

module.exports = fetchCascades;
```

And in `api.js`, add the import:

```javascript
const fetchCascades = require('./utils/fetchCascades');
```

Catch the specific error thrown when calling `fetchCascades`. We can enhance our error logging for better insights. Update `api.js` to include detailed logging:

```javascript
router.get('/cascades', (req, res) => {
    try {
        const cascades = fetchCascades();
        res.json(cascades);
    } catch (error) {
        console.error('Error fetching cascades:', error);
        return res.status(500).json({ error: 'Internal Server Error' });
    }
